        s.append(L10nCatalogSample(key: "legal.terms.materials.header", table: "Legal", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Legal.termsMaterialsHeader }, expected: ["ja": "使用している素材について", "ko": "사용하는 소재에 대해"]))
